window.ANDRE_IMG={"accovacciato": "data:image/png;base64,", "aterra": "data:image/png;base64,", "calcio": "data:image/png;base64,", "camminata1": "data:image/png;base64,", "camminata2": "data:image/png;base64,", "caricapugno": "data:image/png;base64,", "colpito": "data:image/png;base64,", "coro": "data:image/png;base64,", "f24": "data:image/png;base64,", "guardia": "data:image/png;base64,", "kart1": "data:image/png;base64,", "kart2": "data:image/png;base64,", "ko": "data:image/png;base64,", "lancio": "data:image/png;base64,", "montante": "data:image/png;base64,", "parata": "data:image/png;base64,", "provocazione": "data:image/png;base64,", "pugno": "data:image/png;base64,", "rialzo": "data:image/png;base64,", "ritratto": "data:image/png;base64,", "salto": "data:image/png;base64,", "sciarpa": "data:image/png;base64,", "sconfitta": "data:image/png;base64,", "sgambetto": "data:image/png;base64,", "stordito": "data:image/png;base64,", "tifo": "data:image/png;base64,", "timbro": "data:image/png;base64,", "vittoria": "data:image/png;base64,"};window.ANDRE_SCR={"ACCERTAMENTO": "data:image/png;base64,", "CURVA": "data:image/png;base64,", "F24": "data:image/png;base64,", "MAXIMUM_ATTACK": "data:image/png;base64,", "SCIARPATA": "data:image/png;base64,", "VIULEEENZA": "data:image/png;base64,"};window.ANDRE_SRC="\nQUOTES.andre={intro:[\"Hai pagato l'F24?\",\"Ultimo avviso prima dell'accertamento.\",\"MAXIMUM ATTACK!\",\"Fratello o no, ti tasso.\"],win:[\"Ravvedimento operoso: troppo tardi.\",\"Saldo e stralcio. Tu sei lo stralcio.\",\"Archiviato. Con sanzione.\"],lose:[\"Ricorso in commissione tributaria.\",\"Geme... vendicami.\",\"Era deducibile.\"]};\nCOUPLE.andre=COUPLE.andre||{}; COUPLE.andre.geme={intro:[\"Fratellino, la tua parcella e' in nero.\"],win:[\"Ti ho dichiarato a carico.\"],lose:[\"Va bene, il Negroni lo pago io.\"]};\nCOUPLE.geme=COUPLE.geme||{}; COUPLE.geme.andre={intro:[\"AndVe... ti distVuggo.\"],win:[\"AndVe, ti ho mangiato il cuoVe.\"],lose:[\"PoVca tVoia, AndVe...\"]};\nCOUPLE.andre.stefano={intro:[\"SDB, la tua fattura e' sbagliata.\"],win:[\"Accertamento chiuso.\"],lose:[\"Mi avvalgo della facolta' di non rispondere.\"]};\nCOUPLE.andre.cugi={intro:[\"Cugi, mischia e poi dichiarazione dei redditi.\"],win:[\"Placcato e tassato.\"],lose:[\"Mai sfidare un rugbista in giacca.\"]};\nCOUPLE.andre.allibrator={intro:[\"Allibratore, le vincite vanno dichiarate.\"],win:[\"Quota tassata al 26%.\"],lose:[\"Va bene, offri tu.\"]};\nCOUPLE.andre.ciuppa={intro:[\"Ciuppa, la birra e' deducibile?\"],win:[\"No. Non lo e'.\"],lose:[\"Terzo tempo pagato da me.\"]};\nif(SPRITES.andre){ const N=SPRITES.andre; N.guardia2=N.guardia; N.paratabassa=N.accovacciato; N.presa=N.pugno; N.entrata=N.provocazione; N.lancio2=N.lancio; N.caricacalcio=N.caricapugno; N.sguardo=N.provocazione; N.turbo=N.pugno; N.sfondamento=N.pugno; N.stordita=N.stordito; N.super1=N.kart1; N.super2=N.kart1; N.esulta1=N.vittoria; N.esulta2=N.tifo; N.esulta3=N.vittoria; N.volo=N.ko; N.svenuto0=N.aterra; N.vittoria2=N.vittoria; N.vittoria3=N.vittoria; }\n/* ANDRE1 - EVIL GEME base: F24 lanciato, timbro dell'accertamento (speciale), super go-kart MAXIMUM ATTACK (guida lui).\n   Evoluzione ULTRAS: sciarpa lanciata, coro da curva (speciale), super carica a cavallo della zebra con la picca, VIULEEENZA! */\nfunction andreImg(n){ const D=window.ANDRE_IMG||{}, c=SPRITES.__aImg=SPRITES.__aImg||{}; if(!D[n]) return null; if(!c[n]){ const i=new Image(); i.src=D[n]; c[n]=i; } return c[n].complete&&c[n].width?c[n]:null; }\nfunction drawAndreProj(p){ let im, s=1, rot=0;\n  if(p.kind==='f24'){ im=andreImg('f24'); s=0.55; rot=Math.sin(G.frame*0.4)*0.4; }\n  else if(p.kind==='sciarpa'){ im=andreImg('sciarpa'); s=0.6; rot=(G.frame%30)/30*Math.PI*2*(p.vx<0?-1:1); }\n  else if(p.atimbro){ im=andreImg('timbro'); s=0.7; }\n  else if(p.acoro){ im=andreImg('coro'); s=0.8*(0.9+0.1*Math.sin(G.frame*0.6)); }\n  if(!im) return false; ctx.save(); ctx.translate(p.x,p.y); ctx.scale(p.vx<0?-1:1,1); if(rot) ctx.rotate(rot); ctx.imageSmoothingEnabled=false; ctx.drawImage(im,-im.width*s/2,-im.height*s/2,im.width*s,im.height*s); ctx.restore(); return true; }\ntry{ setTimeout(()=>['f24','sciarpa','timbro','coro'].forEach(andreImg),0); }catch(e){}\nfunction andreCarica(f,o,a,m,fwd){ /* go-kart (base) o zebra (ultras): guida lui, attraversa lo schermo */\n  const ev=f.def.lv>=2;\n  if(a.f<m.s){ f.vx=0; return; }\n  if(a.f===m.s){ f.acar={hit:0,fwd,ev}; G.excite=1; SFX.swing&&SFX.swing(); G.shake=Math.max(G.shake,5); floatText(ev?'VIULEEENZA!':'MAXIMUM ATTACK!',f.x,f.y-270,ev?'#ffffff':'#ff3a2a',26,60); try{ tone('sawtooth',ev?90:180,ev?300:900,.5,.09); }catch(e){} }\n  const Q=f.acar||(f.acar={hit:0,fwd,ev});\n  if(Q.hit>0){ Q.hit++; f.vx=fwd*2; return; }\n  f.vx=fwd*13;\n  if(a.f%2===0) for(let k=0;k<2;k++) FX.push({x:f.x-fwd*(40+rnd()*60),y:f.y-6-rnd()*14,vx:-fwd*(1+rnd()*2),vy:-1-rnd()*2,life:18,c:ev?(rnd()<.5?'#ffffff':'#1a1a1a'):(rnd()<.5?'#c8b49a':'#efe4d2')});\n  if(o&&!['ko','down'].includes(o.state)){ const dist=(o.x-f.x)*fwd;\n    if(dist>-10&&dist<150&&o.y>f.y-90){ hit(f,o,ev?20:18,14,40,{sup:true,heavy:true,launch:true,dirx:fwd,y:o.y-130}); Q.hit=1;\n      if(o.state==='hit'){ floatText('SBAM!',o.x,o.y-215,ev?'#ffffff':'#ff3a2a',28,60); G.shake=Math.max(G.shake,12); } } } }\nfunction stepAndre(f,o){ if(f.acar&&(!f.atk||f.atk.type!=='sup')) f.acar=null; }\n";